add('ascii_digits', 'text: str', 'Keep only ASCII characters 0 through 9, in original order.', "return ''.join(c for c in text if '0' <= c <= '9')", [(['a1b2'], '12'),([''],''),(['001-10'],'00110'),(['١２3'],'3')])
add('title_tokens', 'text: str', 'Split on whitespace; uppercase the first code point and lowercase the remaining substring of each token; join with one space.', "return ' '.join(w[0].upper()+w[1:].lower() for w in text.split())", [(['hELLO wORLD'],'Hello World'),([''],''),(['a a'],'A A'),(['éCOLE\tX-Y'],'École X-y')])
add('char_counts', 'text: str', 'Count each Unicode code point, case sensitive, with keys in first encounter order, including whitespace.', 'out = {}\nfor c in text: out[c] = out.get(c, 0) + 1\nreturn out', [(['aba'],{'a':2,'b':1}),([''],{}),(['bbaa'],{'b':2,'a':2}),(['é é'],{'é':2,' ':1})])

add('rotate_list', 'items: list[int], offset: int', 'Rotate left by offset modulo length, allowing negative offsets; empty returns empty.', 'if not items: return []\nk = offset % len(items)\nreturn items[k:] + items[:k]', [([[1,2,3],1],[2,3,1]),([[],9],[]),([[1,2,1],-1],[1,1,2]),([[1,2],4],[1,2])])
add('explicit_order', 'items: list[str], priority: list[str]', 'priority contains unique strings. Sort listed strings by priority, preserving duplicate order, then append unlisted items in original order.', 'rank = {x: i for i, x in enumerate(priority)}\nreturn sorted(items, key=lambda x: rank.get(x, len(rank)))', [([['c','a','b'],['b','a']],['b','a','c']),([[],[]],[]),([['z','a','z','b','a'],['a']],['a','a','z','z','b']),([['b','a'],[]],['b','a'])])
add('intersection', 'left: list[int], right: list[int]', 'Return distinct common values in first left occurrence order.', 'return list(dict.fromkeys(x for x in left if x in right))', [([[3,1,2],[2,3]],[3,2]),([[],[1]],[]),([[2,2,1],[1,2,2]],[2,1]),([[0,-1],[9]],[])])
add('difference', 'left: list[int], right: list[int]', 'Return all left elements absent from right, retaining left order and duplicates.', 'return [x for x in left if x not in right]', [([[1,2,3],[2]],[1,3]),([[],[]],[]),([[2,2,1],[1]],[2,2]),([[-1,0],[]],[-1,0])])
add('union', 'left: list[int], right: list[int]', 'Return distinct values in first encounter order across left then right.', 'return list(dict.fromkeys(left + right))', [([[2,1],[1,3]],[2,1,3]),([[],[]],[]),([[2,2],[2,1,1]],[2,1]),([[],[-1,0]],[-1,0])])
add('frequencies_sorted', 'items: list[int]', 'Return [value,count] pairs sorted by descending count, then ascending numeric value.', 'counts = {}\nfor x in items: counts[x] = counts.get(x, 0)+1\nreturn [[x, counts[x]] for x in sorted(counts, key=lambda x: (-counts[x], x))]', [([[2,1,2]],[[2,2],[1,1]]),([[]],[]),([[3,1,3,1]],[[1,2],[3,2]]),([[-1,0,-1]], [[-1,2],[0,1]])])
add('run_lengths', 'items: list[int]', 'Return [value,count] pairs for adjacent equal runs in input order; separate nonadjacent equal runs.', 'out = []\nfor x in items:\n    if out and out[-1][0] == x: out[-1][1] += 1\n    else: out.append([x,1])\nreturn out', [([[1,1,2,1]],[[1,2],[2,1],[1,1]]),([[]],[]),([[2,2,2]],[[2,3]]),([[-1,0,0]],[[-1,1],[0,2]])])
add('expand_runs', 'runs: list[list[int]]', 'Each run is [integer value, nonnegative count]. Concatenate repeated values in run order; zero count contributes nothing.', 'return [value for value, count in runs for _ in range(count)]', [([[[2,2],[1,1]]],[2,2,1]),([[]],[]),([[[1,1],[2,0],[1,2]]],[1,1,1]),([[[-1,2]]],[-1,-1])])
add('zip_fill', 'left: list[int], right: list[int], fill: int', 'Return two-element lists at corresponding positions through the longer input; fill missing positions with fill.', 'return [[left[i] if i < len(left) else fill, right[i] if i < len(right) else fill] for i in range(max(len(left),len(right)))]', [([[1,2],[3],0],[[1,3],[2,0]]),([[],[],9],[]),([[2,2],[1,1],0],[[2,1],[2,1]]),([[],[-1],8],[[8,-1]])])
add('split_on', 'items: list[int], delimiter: int', 'Split at each delimiter and omit delimiter values. Keep empty segments, including leading/trailing and the one segment of an empty input.', 'out = [[]]\nfor x in items:\n    if x == delimiter: out.append([])\n    else: out[-1].append(x)\nreturn out', [([[1,0,2],0],[[1],[2]]),([[],0],[[]]),([[0,0],0],[[],[],[]]),([[1,2],9],[[1,2]])])


def main():
    logging.basicConfig(level=logging.INFO, format='%(asctime)s %(levelname)s %(message)s')
    assert len(UNITS) == 80 and len({u['name'] for u in UNITS}) == 80
    for directory in ('workspace/ops', 'workspace/docs', 'workspace/tests', 'private/reference/ops', 'private/tests'):
        (ROOT / directory).mkdir(parents=True, exist_ok=True)
    for path in ('workspace/ops/__init__.py', 'private/reference/ops/__init__.py'):
        (ROOT / path).write_text('"""Independent bulk operations. Import individual modules explicitly."""\n')
    index = ['# Bulk operations index', '', 'Implement all 80 independent functions. Python stdlib only.', '',
             'All inputs have the documented types and satisfy stated preconditions; no validation of invalid inputs is required. Integers exclude bool. Strings use Unicode code points unless an ASCII rule is specified. No function may mutate any input, including nested containers. Return fresh lists/dicts at every container level that the specification constructs; row copies are shallow. Dict insertion order is observable, including nested dictionaries. No cross-function dependence is required. Empty inputs, duplicate handling and order follow each section below. Return types are stated per function. All 80 functions start as importable stubs that raise NotImplementedError only when called.', '', '| ID | Signature | Module | Specification |', '|---|---|---|---|']
    for module in range(40):
        subset = UNITS[module*2:module*2+2]
        stub, reference = [], []
        for u in subset:
            u['module'] = f'm{module+1:02d}'
            header = f"def {u['name']}({u['signature']}):\n"
            stub.append(header + '    raise NotImplementedError\n')
            reference.append(header + '\n'.join('    '+line for line in u['body'].splitlines())+'\n')
        for folder, content in (('workspace',stub), ('private/reference',reference)):
            (ROOT / folder / 'ops' / f'm{module+1:02d}.py').write_text('\n\n'.join(content))
    for chapter in range(8):
        doc = [f'# Volume {chapter+1}', '', 'Common type, order and nonmutation rules: [index](INDEX.md).', '']
        for i in range(chapter*10, chapter*10+10):
            u = UNITS[i]
            u['id'] = f'U{i+1:03d}'
            expected = u['cases'][0][1]
            typename = type(expected).__name__
            if u['name'] in ('argmax_first','nearest_zero'): typename = 'int | None'
            signature = f"{u['name']}({u['signature']}) -> {typename}"
            table_signature = signature.replace("|", chr(92) + "|")
            index.append(f"| {u['id']} | `{table_signature}` | `ops/{u['module']}.py` | [Volume {chapter+1} §{u['name']}](V{chapter+1}.md#{u['name']}) |")
            doc.extend([f"## {u['name']}", '', f"{u['id']}: `{signature}`", '', u['rule'], '', f"Example: arguments `{u['cases'][0][0]!r}` → `{expected!r}`.", ''])
            test = 'from copy import deepcopy\nimport pytest\n\n'
            test += '@pytest.mark.parametrize("args, expected", '+repr(u['cases'])+')\n'
            test += f"def test_{u['name']}(args, expected):\n    from ops.{u['module']} import {u['name']}\n    original = deepcopy(args)\n    result = {u['name']}(*args)\n    assert result == expected\n    assert type(result) is type(expected)\n    assert args == original\n"
            # Recursive order and alias checks test only documented container construction.
            test += '    def ordered(value):\n        if isinstance(value, dict):\n            return [(k, ordered(v)) for k, v in value.items()]\n        if isinstance(value, list):\n            return [ordered(v) for v in value]\n        return value\n    assert ordered(result) == ordered(expected)\n    assert ordered(args) == ordered(original)\n'
            test += '    input_ids = set()\n    def remember(value):\n        if isinstance(value, (list, dict)):\n            input_ids.add(id(value))\n            for child in (value.values() if isinstance(value, dict) else value):\n                remember(child)\n    remember(args)\n    def fresh(value):\n        if isinstance(value, (list, dict)):\n            assert id(value) not in input_ids\n            for child in (value.values() if isinstance(value, dict) else value):\n                fresh(child)\n    fresh(result)\n'
            (ROOT / 'private/tests' / f"test_{u['name']}.py").write_text(test)
        (ROOT / 'workspace/docs' / f'V{chapter+1}.md').write_text('\n'.join(doc))
    (ROOT / 'workspace/docs/INDEX.md').write_text('\n'.join(index)+'\n')
    public = ['"""One public golden example per independent operation."""', '']
    for u in UNITS:
        public += [f"def test_{u['name']}():", f"    from ops.{u['module']} import {u['name']}", f"    assert {u['name']}(*{u['cases'][0][0]!r}) == {u['cases'][0][1]!r}", '']
    (ROOT / 'workspace/tests/test_public.py').write_text('\n'.join(public))
    (ROOT / 'fixture.json').write_text(json.dumps(dict(name='bulk_ops', axes=['volume'], allowed=['ops/'], public_tests=['tests/'], grading_timeout_s=300), indent=2)+'\n')
    (ROOT / 'task.md').write_text('Implement all 80 independent operations in the ops package. Read docs/INDEX.md for the complete signature/module index and the eight specification volumes. Preserve signatures, return the documented types and order, and do not mutate inputs. Change ops/ only; do not edit tests or docs. Stdlib only. You may use shared helpers or generation scripts within ops/ to implement the rules.\nRun from workspace root: `uv run -q --no-project --with pytest python -m pytest -q tests/`\nDo not commit. Return changed files, test results and anything unverified.\n')
    (ROOT / 'workspace/README.md').write_text('# Bulk operations\n\nThe 40 modules in `ops/` each expose two independent functions. `docs/INDEX.md` indexes all 80 specifications in eight volumes of ten. `tests/test_public.py` supplies one example per function. All functions are currently importable stubs. Implement all units.\n\nRun: `uv run -q --no-project --with pytest python -m pytest -q tests/`\n')
    (ROOT / 'private/units.json').write_text(json.dumps(UNITS, indent=2, ensure_ascii=False)+'\n')
    logging.info('build_complete root=%s modules=40 units=80 public=80 hidden=320', ROOT)

if __name__ == '__main__':
    main()
